const since24 = () => { const d = new Date(Date.now() - 24 * 3600e3); return jStr(d) + ' ' + jpad(d.getHours()) + ':' + jpad(d.getMinutes()); };

let ME = { id: '', name: '', ext: '', role: 'operator', perms: {} };
