        if (!d.topic) return set({ err: 'موضوع ارجاع را انتخاب کنید' });
        if (d.text.trim().length < 10) return set({ err: 'توضیح ارجاع را دقیق بنویسید (حداقل ۱۰ حرف)' });
        set({ busy: true });
