      hasFu: r.outcome === 'follow' && !!r.followUp, fu: 'پیگیری: ' + fa(r.followUp || ''), fuBg: overdue ? '#fdeceb' : '#fcf3e0', fuFg: overdue ? '#b42318' : '#8a5a00',
      ini: (r.by || '؟').trim().slice(0, 1), mine,
