    ...c, ini: ini(c.name), dirLabel: c.dir === 'in' ? 'ورودی' : 'خروجی', status: ST[c.st] || ST.missed, histTitle: c.short ? 'وصل شد ولی کمتر از ۵ ثانیه طول کشید (بی‌پاسخ حساب شد)' : c.callback ? (c.st === 'answered' ? 'تماس برگشتی برقرار شد' : 'تماس برگشتی بی‌پاسخ') : HIST[c.st],
    op, opName: op ? op.name : 'IVR', ext: op ? op.ext : '—', durText: c.dur ? fmt(c.dur) : '—', waitText: c.wait + ' ثانیه',
    hasVoice: !!c.hasRec, noVoice: !c.hasRec, ai, hasAi: !!(ai && !ai.pending), noAi: !(ai && !ai.pending),
